// Verify the HMAC signature and timestamp, and detect duplicate deliveries.
const crypto = require('crypto');
const secret = $env.OPSDESK_WEBHOOK_SECRET || '';
const item = $input.first();
const headers = item.json.headers || {};

// Prefer the exact raw body; fall back to re-serialising the parsed JSON.
const raw = item.binary?.data?.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body);

const timestamp = headers['x-opsdesk-timestamp'] || '';
const provided = headers['x-opsdesk-signature'] || '';
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest('hex');
const fresh = Math.abs(Date.now() / 1000 - Number(timestamp)) < 300; // 5 minute replay window
const valid = Boolean(secret) && fresh && provided.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(provided), Buffer.from(expected));

const eventId = headers['x-opsdesk-event-id'] || '';
const seen = $getWorkflowStaticData('global').seen || {};

return [{ json: { valid, duplicate: Boolean(seen[eventId]), eventId, event: item.json.body } }];

// Build the notification email for each event type.
const { event, eventId } = $input.first().json;
const d = event.data || {};
const ref = `${d.ticketNumber} – ${d.subject}`;
const footer = `\n\nView the ticket: ${d.url}\n\nThis is an automated message from OpsDesk AI.`;
let email = null;

switch (event.type) {
  case 'ticket.created':
    email = { to: d.requester?.email, subject: `[${d.ticketNumber}] We received your request`,
      text: `Hi ${d.requester?.name},\n\nYour support ticket "${d.subject}" was created with ${d.priority} priority. The IT team will pick it up shortly.${footer}` };
    break;
  case 'ticket.assigned':
    email = d.assignee && { to: d.assignee.email, subject: `[${d.ticketNumber}] Ticket assigned to you`,
      text: `Hi ${d.assignee.name},\n\n${ref} (${d.priority} priority) has been assigned to you.${footer}` };
    break;
  case 'ticket.status_changed':
    // The resolved event sends its own email, so skip the duplicate status email.
    if (d.change?.to !== 'resolved') {
      email = { to: d.requester?.email, subject: `[${d.ticketNumber}] Status updated: ${String(d.change?.to).replaceAll('_', ' ')}`,
        text: `Hi ${d.requester?.name},\n\nThe status of ${ref} changed from ${String(d.change?.from).replaceAll('_', ' ')} to ${String(d.change?.to).replaceAll('_', ' ')}.${footer}` };
    }
    break;
  case 'ticket.resolved':
    email = { to: d.requester?.email, subject: `[${d.ticketNumber}] Your ticket was resolved`,
      text: `Hi ${d.requester?.name},\n\nIT marked ${ref} as resolved. Please open the ticket to confirm the fix or reopen it if the problem continues.${footer}` };
    break;
  default:
    email = null; // e.g. integration.test: acknowledged without sending email
}

return [{ json: { eventId, type: event.type, sendEmail: Boolean(email?.to), ...(email || {}) } }];

// Record the event id only AFTER the email step succeeded, so a failed send is retried by OpsDesk.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const eventId = $('Compose email').first().json.eventId;
store.seen[eventId] = Date.now();
// Keep the idempotency window bounded (7 days).
const cutoff = Date.now() - 7 * 24 * 3600 * 1000;
for (const [id, at] of Object.entries(store.seen)) if (at < cutoff) delete store.seen[id];
return [{ json: { status: 'processed', eventId } }];
